import{_ as a,o as n,c as i,ag as s}from"./chunks/framework.CmaAMB6e.js";const p=JSON.parse('{"title":"iOS 学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"ios/learning-path.md","filePath":"ios/learning-path.md","lastUpdated":1784195062000}'),r={name:"ios/learning-path.md"};function o(l,t,e,d,g,c){return n(),i("div",null,[...t[0]||(t[0]=[s(`<h1 id="ios-学习路径" tabindex="-1">iOS 学习路径 <a class="header-anchor" href="#ios-学习路径" aria-label="Permalink to &quot;iOS 学习路径&quot;">​</a></h1><blockquote><p>iOS 专属的概念序列与阶段划分。每个概念自成闭环,不与其他技能绑定。</p></blockquote><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li><strong>概念驱动</strong>:按概念顺序推进,每个概念是一篇完整教程</li><li><strong>前端对照</strong>:每篇末尾有「前端对照」小节,用你已会的 React/Vue/JS 帮助理解</li><li><strong>边学边练</strong>:每篇配练习建议,可用 <code>/practice ios &lt;概念&gt;</code> 生成针对性练习</li></ul><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>概念数</th></tr></thead><tbody><tr><td>1</td><td>基础层</td><td>5</td></tr><tr><td>2</td><td>UI 层</td><td>8</td></tr><tr><td>3</td><td>工程层</td><td>5</td></tr><tr><td>4</td><td>平台特性与实战</td><td>2</td></tr><tr><td>5</td><td>资深层</td><td>8</td></tr></tbody></table><hr><h2 id="阶段-1-·-基础层" tabindex="-1">阶段 1 · 基础层 <a class="header-anchor" href="#阶段-1-·-基础层" aria-label="Permalink to &quot;阶段 1 · 基础层&quot;">​</a></h2><p>打地基,建立 iOS + Swift 的最小可用认知。</p><ul><li><strong>01 Hello World 与项目结构</strong> - 跑通第一个程序,理解 SwiftUI 项目骨架、Xcode 构建与运行流程</li><li><strong>02 语法基础</strong> - 变量、类型、控制流、函数</li><li><strong>03 集合与数据结构</strong> - Array / Dictionary / Set 及常用操作</li><li><strong>04 异步编程</strong> - async/await、actor</li><li><strong>05 错误处理与空安全</strong> - optional、throwing</li></ul><h2 id="阶段-2-·-ui-层" tabindex="-1">阶段 2 · UI 层 <a class="header-anchor" href="#阶段-2-·-ui-层" aria-label="Permalink to &quot;阶段 2 · UI 层&quot;">​</a></h2><p>进入 SwiftUI 的声明式 UI 开发。</p><ul><li><strong>06 声明式 UI 思想</strong> - struct View + body 状态驱动</li><li><strong>07 布局系统</strong> - HStack / VStack / ZStack / 修饰符</li><li><strong>08 组件化与复用</strong> - 视图组合、Props、内容复用</li><li><strong>09 状态管理</strong> - @State / @Binding / @Environment</li><li><strong>10 列表渲染与虚拟滚动</strong> - List / LazyVStack</li><li><strong>11 导航与路由</strong> - NavigationStack、页面栈</li><li><strong>12 表单与用户输入</strong> - 受控输入、校验</li><li><strong>13 动画与过渡</strong> - withAnimation / transition</li></ul><h2 id="阶段-3-·-工程层" tabindex="-1">阶段 3 · 工程层 <a class="header-anchor" href="#阶段-3-·-工程层" aria-label="Permalink to &quot;阶段 3 · 工程层&quot;">​</a></h2><p>进入工程化能力。</p><ul><li><strong>14 网络请求与 API 调用</strong> - URLSession / Codable / async</li><li><strong>15 本地存储与持久化</strong> - CoreData / SwiftData / UserDefaults</li><li><strong>16 依赖管理与包管理</strong> - Swift Package Manager</li><li><strong>17 测试</strong> - XCTest</li><li><strong>18 调试与性能分析</strong> - Instruments</li></ul><h2 id="阶段-4-·-平台特性与实战" tabindex="-1">阶段 4 · 平台特性与实战 <a class="header-anchor" href="#阶段-4-·-平台特性与实战" aria-label="Permalink to &quot;阶段 4 · 平台特性与实战&quot;">​</a></h2><ul><li><strong>19 平台特有能力</strong> - 权限、通知、文件系统、后台任务、生命周期</li><li><strong>20 综合实战项目</strong> - 串联前 19 个概念,做一个完整 App</li></ul><h2 id="阶段-5-·-资深层" tabindex="-1">阶段 5 · 资深层 <a class="header-anchor" href="#阶段-5-·-资深层" aria-label="Permalink to &quot;阶段 5 · 资深层&quot;">​</a></h2><p>进阶到资深/专家水平,覆盖内存、架构、并发、质量与交付。</p><ul><li><strong>21 内存管理（ARC）</strong> - 引用计数、retain cycle、weak/unowned、泄漏检测</li><li><strong>22 架构模式（MVVM / TCA）</strong> - 单向数据流、ViewModel、Repository、TCA</li><li><strong>23 Swift Concurrency 深入</strong> - actor、Sendable、结构化并发、AsyncSequence</li><li><strong>24 崩溃分析与符号化</strong> - 异常类型、Crashlytics、dSYM 符号化、崩溃治理</li><li><strong>25 性能优化（Instruments 深入）</strong> - Time Profiler、body 重算、图片列表、启动优化</li><li><strong>26 签名与发布</strong> - 证书/描述文件、TestFlight、App Store 发布</li><li><strong>27 国际化与无障碍</strong> - Localizable、RTL、Dynamic Type、VoiceOver</li><li><strong>28 Combine 与响应式编程</strong> - Publisher、操作符、背压、与 async/await 取舍</li></ul><hr><h2 id="概念依赖关系" tabindex="-1">概念依赖关系 <a class="header-anchor" href="#概念依赖关系" aria-label="Permalink to &quot;概念依赖关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>01 -&gt; 02 -&gt; 03 -&gt; 04 -&gt; 05          (基础层串行)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        06 -&gt; 07 -&gt; ... -&gt; 13        (UI 层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>        14 -&gt; 15 -&gt; 16 -&gt; 17 -&gt; 18   (工程层)</span></span>
<span class="line"><span>                ↓</span></span>
<span class="line"><span>              19 -&gt; 20               (实战)</span></span></code></pre></div><h2 id="进度跟踪" tabindex="-1">进度跟踪 <a class="header-anchor" href="#进度跟踪" aria-label="Permalink to &quot;进度跟踪&quot;">​</a></h2><p>每完成一个概念,在 <code>progress.md</code> 更新状态:⬜ 未开始 / 🔄 学习中 / ✅ 已掌握。</p>`,26)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
